// base's conventions: system-prompt sections for the main session, added context for every subagent.
// The engine has no event for a subagent's system prompt, so its share rides classic SubagentStart. A session
// no surface draws (a cloud session, `claude -p`) gets its prompt composed without the plugins and no classic
// SessionStart: there the sections go in as a prompt.context block of the first user message, and
// prompt.compose adds nothing.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, On, PromptComposeSection } from 'claude-code'
import type { BaseDelivery } from '../../types'
import {
  COMMENT_DISCIPLINE,
  LEAN_CODE,
  NO_CODE_AGENT,
  SHOPIFY_POINTER,
  TASK_WORKSPACE,
  UNTRUSTED_CONTENT,
  WRITING_STYLE,
  rootLine,
  withRoot,
} from './conventions/text.ts'
import { dogfoodMode, dogfoodSection, enabledNames, versionsLine, versionsOf } from './dogfood/text.ts'

type $ = EngineInterface

/** How many system prompts the engine composed through base's hook this session: 0 = the conventions never reached the model (doctor.ts reads it). */
const composed = atom({ plugin: 'base', key: 'composed' } as const, 0)
/** The session id whose first user message carries the conventions as a context block (doctor.ts reads it): prompt.compose then adds nothing. */
const injected = atom({ plugin: 'base', key: 'injected' } as const, null as string | null)
/** What the prompt events did this session, for the doctor: which of them a host fires decides how the conventions travel. */
const delivery = atom({ plugin: 'base', key: 'delivery' } as const, { sid: null, startSurfaces: null, prompts: 0, context: false } as BaseDelivery)
const slimInfo = atom({ plugin: 'slim', key: 'info' } as const, null)

/** The Domaine plugins and versions dogfood mode names; dogfood.ts reads the same sources for a report's Environment. */
async function pluginVersions($: $): Promise<string> {
  const home = (await $.env.get('HOME'))?.trim() ?? ''
  const cfgEnv = (await $.env.get('CLAUDE_CONFIG_DIR'))?.trim() ?? ''
  const config = cfgEnv.startsWith('/') ? cfgEnv.replace(/\/+$/, '') : home.startsWith('/') ? `${home.replace(/\/+$/, '')}/.claude` : null
  const installed = config ? await $.fs.read(`${config}/plugins/installed_plugins.json`).catch(() => null) : null
  let own = 'unknown'
  try {
    const v = (JSON.parse(await $.fs.read(`${$.plugin.root}/.claude-plugin/plugin.json`)) as { version?: unknown }).version
    if (typeof v === 'string' && v) own = v
  } catch {}
  const slim = (await read($, slimInfo).catch(() => null))?.version ?? null
  const enabled = enabledNames(await $.settings.read().catch(() => null))
  return versionsLine(versionsOf(installed, $.plugin.root, own, slim, enabled))
}

const dogfoodOn = async ($: $) =>
  dogfoodMode((await $.env.get('BASE_DOGFOOD')) ?? '', (await $.env.get('CLAUDE_CODE_ACCOUNT_UUID')) ?? '', await $.fs.read(`${$.plugin.root}/dogfood.json`).catch(() => null))

/** The dogfood section when dogfood mode is on, worded for a session no surface draws where none does; else null. */
async function dogfood($: $): Promise<string | null> {
  if (!(await dogfoodOn($))) return null
  const surfaceless = (await $.session.surfaces().catch(() => null))?.length === 0
  return dogfoodSection(await pluginVersions($), surfaceless)
}

/**
 * The sections in session order, each `base:<name>`: the switches are read on every render, and the
 * text depends on nothing else but the plugin versions and the surfaces in the dogfood section, so a render
 * repeats the last one byte for byte (the prompt cache).
 */
export async function sections($: $): Promise<PromptComposeSection[]> {
  const root = $.plugin.root
  const lean = (await $.env.get('BASE_LEAN')) !== '0'
  const ste = (await $.env.get('BASE_STE')) !== '0'
  const parts: [string, string][] = [
    ['root', rootLine(root)],
    ['comment-discipline', COMMENT_DISCIPLINE],
    ['task-workspace', withRoot(TASK_WORKSPACE, root)],
    ['untrusted-content', UNTRUSTED_CONTENT],
    ['shopify', SHOPIFY_POINTER],
  ]
  if (lean) parts.push(['lean-code', LEAN_CODE])
  if (ste) parts.push(['writing-style', WRITING_STYLE])
  const df = await dogfood($)
  if (df) parts.push(['dogfood', df])
  return parts.map(([name, text]) => ({ id: `base:${name}`, text, scope: 'session' }))
}

/**
 * The root line and the untrusted-content rail for every agent; the code conventions for one that writes code;
 * the dogfood section in dogfood mode, since any agent may run a plugin script. Empty for a fork: it inherits the parent's system prompt, which already carries base's sections.
 */
export async function subagentContext($: $, agentType: string): Promise<string> {
  if (agentType === 'fork') return ''
  const parts = [rootLine($.plugin.root), UNTRUSTED_CONTENT]
  if (!NO_CODE_AGENT.test(agentType)) {
    parts.push(COMMENT_DISCIPLINE)
    if ((await $.env.get('BASE_LEAN')) !== '0') parts.push(LEAN_CODE)
  }
  const df = await dogfood($)
  if (df) parts.push(df)
  return parts.join('\n\n')
}

/** The sections as one context block for a session no surface draws; null where one does (the system prompt carries them). */
export async function contextBlock($: $): Promise<string | null> {
  if ((await $.session.surfaces()).length > 0) return null
  return (await sections($)).map(s => s.text).join('\n\n')
}

export function registerConventions(on: On): void {
  // Matched apart from title.ts's hook: one unmatched hook per event per plugin.
  on('classic.SessionStart', { source: /^/ }, async ($, e, next) => {
    const r = await next(e)
    const sid = String(await $.session.id())
    const seen = await $.session.surfaces().catch(() => null)
    await update($, delivery, d => ({ ...(d.sid === sid ? d : { sid, prompts: 0, context: false }), sid, startSurfaces: seen ? [...seen] : null })).catch(() => {})
    return r
  })

  on('prompt.compose', async ($, e, next) => {
    const r = await next(e)
    await update($, composed, n => n + 1).catch(() => {})
    if ((await read($, injected).catch(() => null)) === String(await $.session.id())) return r
    const ours = await sections($).catch(() => [])
    const taken = new Set(r.sections.map(s => s.id))
    return { sections: [...r.sections, ...ours.filter(s => !taken.has(s.id))] }
  })

  // Matched apart from title.ts's hook. Counts the prompts a host hands the classic hook.
  on('classic.UserPromptSubmit', { prompt: /^/ }, async ($, e, next) => {
    const r = await next(e)
    const sid = String(await $.session.id())
    await update($, delivery, d => ({ ...(d.sid === sid ? d : { sid, startSurfaces: null, context: false }), sid, prompts: (d.sid === sid ? d.prompts : 0) + 1 })).catch(() => {})
    return r
  })

  on('prompt.context', async ($, e, next) => {
    const r = await next(e)
    const sid = String(await $.session.id())
    await update($, delivery, d => ({ ...(d.sid === sid ? d : { sid, startSurfaces: null, prompts: 0 }), sid, context: true })).catch(() => {})
    const text = await contextBlock($).catch(() => null)
    if (text === null) return r
    await update($, injected, () => sid).catch(() => {})
    return { ...r, blocks: [...r.blocks, { name: 'baseConventions', text }] }
  })

  on('classic.SubagentStart', async ($, e, next) => {
    const r = await next(e)
    const ctx = await subagentContext($, e.agent_type ?? '').catch(() => null)
    return ctx ? { ...r, additionalContext: [...(r.additionalContext ?? []), ctx] } : r
  })
}

files.hooks/mods/doctor.ts:
// /base-doctor and the sweeps of base-tmp and of old event-log directories (once per session id; a /clear starts
// a new one). The doctor runs scripts/doctor.cjs for what a node process sees and adds what only a session answers:
// slim's view tool, each MCP server of base's manifest connected; then the tail of base.events.
import { atom, read, update } from 'claude-code'
import type { EngineInterface, On } from 'claude-code'
import type { BaseDelivery, BaseEvent } from '../../types'
import { LOG_TTL_MS, defaultLogRoot, logDir, logLine, pushEvent } from './events.ts'
import type { Disk } from './events.ts'
import { SLIM_MISSING, SLIM_VIEW } from './session.ts'
import { WINDOW_DAYS, dogfoodMode, recent, seen } from './dogfood/text.ts'

export const COMMAND = {
  name: 'base-doctor',
  description: 'Check the base install: node, manifest, slim, MCP servers, base-tmp, event log',
  immediate: true,
} as const
export const MCP_TIMEOUT_MS = 15_000
const TAIL = 10
/** The Figma desktop app serves it locally; base:figma-reader falls back to the REST API without it. */
const LOCAL_SERVER = 'figma-dev-mode'

type Status = 'PASS' | 'FAIL' | 'SKIP' | 'WARN'
export type Row = { status: Status; name: string; detail: string }

const swept = atom({ plugin: 'base', key: 'swept' } as const, null)
const events = atom({ plugin: 'base', key: 'events' } as const, [] as BaseEvent[])
// Written in conventions.ts (renders through prompt.compose; the session whose first message carries the conventions) and
// session.ts (the first prompt's slim check).
const composed = atom({ plugin: 'base', key: 'composed' } as const, 0)
const injected = atom({ plugin: 'base', key: 'injected' } as const, null as string | null)
const delivery = atom({ plugin: 'base', key: 'delivery' } as const, { sid: null, startSurfaces: null, prompts: 0, context: false } as BaseDelivery)
const checked = atom({ plugin: 'base', key: 'checked' } as const, null)

type $ = EngineInterface

/** events.ts's file writer reaches `$` through this: the validator follows `$` only within one file. */
function diskOf($: $): Disk {
  return {
    session: () => $.session.id(),
    home: () => $.env.get('HOME'),
    override: () => $.env.get('DOMAINE_LOG_DIR'),
    manifest: () => $.fs.read(`${$.plugin.root}/.claude-plugin/plugin.json`),
    read: path => $.fs.read(path),
    write: (path, text) => $.fs.write(path, text),
    toast: text => $.ui.toast(text),
  }
}

/** Claude Code's session ids: the sweep touches nothing else, so no dotfile or other directory ever goes. */
const SESSION_ID = /^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}$/i

/**
 * Removes the session directories under `$HOME/.claude/domaine/log` whose newest file is older than 7 days:
 * never this session's, only a session-id name holding nothing but `*.jsonl` files, and never when the root
 * or the directory resolves anywhere but its own spelling (a linked root could point at `~`). `$.fs` has no
 * delete, hence `rm -rf`. A DOMAINE_LOG_DIR is the person's to clean.
 */
async function sweepLogs($: $, sid: string): Promise<void> {
  const root = defaultLogRoot(await $.env.get('HOME'))
  if (!root) return
  if ((await $.fs.stat(root, { resolve: true })).realPath !== root) return
  const now = await $.clock.now()
  for (const d of await $.fs.list(root)) {
    if (d.kind !== 'dir' || d.name === sid || !SESSION_ID.test(d.name)) continue
    const dir = `${root}/${d.name}`
    try {
      const entries = await $.fs.list(dir)
      if (entries.some(f => f.kind !== 'file' || !f.name.endsWith('.jsonl'))) continue
      const newest = entries.length ? Math.max(...entries.map(f => f.mtimeMs)) : (await $.fs.stat(dir)).mtimeMs
      if (now - newest <= LOG_TTL_MS) continue
      if ((await $.fs.stat(dir, { resolve: true })).realPath === dir) await $.process.run(['rm', '-rf', dir], { timeoutMs: 10_000 })
    } catch {}
  }
}

/**
 * The command on every session start (a reload or a re-enable drops it) and at the first prompt of a new
 * session id; the sweeps of `.claude/base-tmp` past BASE_TMP_TTL hours and of the old event-log session
 * directories once per session id, unawaited.
 */
async function arm($: $, start: boolean): Promise<void> {
  try {
    const sid = String(await $.session.id())
    const fresh = (await read($, swept)) !== sid
    if (start || fresh) await $.command.register(COMMAND).catch(() => undefined)
    if (!fresh) return
    await update($, swept, () => sid)
    const argv = ['node', `${$.plugin.root}/scripts/scratch-hygiene.cjs`, '--sweep', await $.session.root()]
    const ttl = await $.env.get('BASE_TMP_TTL')
    if (ttl) argv.push('--ttl-hours', ttl)
    void $.process.run(argv, { timeoutMs: 10_000 }).catch(() => undefined)
    void sweepLogs($, sid).catch(() => undefined)
  } catch {}
}

const STATUSES = new Set(['PASS', 'FAIL', 'SKIP', 'WARN'])

/** doctor.cjs --json rows, or null when its stdout is not that shape. */
export function parseStatic(stdout: string): Row[] | null {
  try {
    const rows = (JSON.parse(stdout) as { rows?: unknown }).rows
    if (!Array.isArray(rows)) return null
    return rows.filter(
      (r): r is Row => !!r && STATUSES.has(r.status) && typeof r.name === 'string' && typeof r.detail === 'string',
    )
  } catch {
    return null
  }
}

async function staticRows($: $): Promise<Row[]> {
  const root = $.plugin.root
  let r
  try {
    const argv = ['node', `${root}/scripts/doctor.cjs`, '--json', '--root', root, '--project', await $.session.root()]
    const dir = logDir(await $.env.get('HOME'), await $.env.get('DOMAINE_LOG_DIR'), await $.session.id())
    if (dir) argv.push('--log-dir', dir)
    r = await $.process.run(argv, { timeoutMs: 30_000 })
  } catch (err) {
    const why = err instanceof Error ? err.message : String(err)
    return [{ status: 'SKIP', name: 'static', detail: `scripts/doctor.cjs did not run (${why}): the static checks need node and the Claude Code CLI` }]
  }
  const rows = parseStatic(r.stdout)
  if (rows?.length) return rows
  const why = (r.stderr.trim().split('\n')[0] ?? '') || 'no rows on stdout'
  return [{ status: 'FAIL', name: 'static', detail: `scripts/doctor.cjs exited ${r.exitCode}: ${why}` }]
}

/** What the prompt events did this session, one clause each: the host's transport the conventions can take. */
async function deliverySeen($: $): Promise<string> {
  const sid = String(await $.session.id())
  const d = await read($, delivery)
  const now = await $.session.surfaces().catch(() => null)
  const same = d.sid === sid
  return [
    same && d.startSurfaces ? `SessionStart saw surfaces [${d.startSurfaces.join(', ')}]` : 'SessionStart never fired',
    `UserPromptSubmit ×${same ? d.prompts : 0}`,
    `prompt.context ${same && d.context ? 'fired' : 'never fired'}`,
    `surfaces now [${now ? now.join(', ') : '?'}]`,
  ].join('; ')
}

async function liveRows($: $): Promise<Row[]> {
  const rows: Row[] = []
  try {
    rows.push((await $.tool.list()).some(t => t.name === SLIM_VIEW)
      ? { status: 'PASS', name: 'slim-live', detail: `${SLIM_VIEW} registered` }
      : { status: 'FAIL', name: 'slim-live', detail: `${SLIM_MISSING}; base refuses its readers until it is` })
  } catch {
    rows.push({ status: 'SKIP', name: 'slim-live', detail: 'the tool list did not answer' })
  }
  try {
    const renders = await read($, composed)
    const prompted = (await read($, checked)) !== null
    const inContext = (await read($, injected)) === String(await $.session.id())
    rows.push(inContext
      ? { status: 'PASS', name: 'conventions', detail: 'in the first user message as a prompt.context block: no surface draws here, so the engine composes its prompt without the plugins' }
      : renders > 0
        ? { status: 'PASS', name: 'conventions', detail: `in the system prompt: ${renders} render${renders === 1 ? '' : 's'} through prompt.compose` }
        : prompted
          ? { status: 'FAIL', name: 'conventions', detail: `not delivered: prompt.compose never fired; ${await deliverySeen($)}` }
          : { status: 'SKIP', name: 'conventions', detail: 'no prompt sent yet: send one, then run the doctor again' })
  } catch {
    rows.push({ status: 'SKIP', name: 'conventions', detail: 'the state did not answer' })
  }
  return rows
}

const dogfoodOn = async ($: $) =>
  dogfoodMode((await $.env.get('BASE_DOGFOOD')) ?? '', (await $.env.get('CLAUDE_CODE_ACCOUNT_UUID')) ?? '', await $.fs.read(`${$.plugin.root}/dogfood.json`).catch(() => null))

/** Dogfood mode's reports of the last 7 days, the home index and this project's folder together; no row when it is off. */
async function defectRows($: $): Promise<Row[]> {
  if (!(await dogfoodOn($))) return []
  try {
    const home = (await $.env.get('HOME'))?.trim() ?? ''
    const index = home.startsWith('/') ? await $.fs.read(`${home.replace(/\/+$/, '')}/.claude/plugin-defects/index.md`).catch(() => '') : ''
    const dir = `${await $.session.root()}/.claude/plugin-defects`
    const names = (await $.fs.list(dir).catch(() => [])).filter(f => f.kind === 'file').map(f => f.name)
    const week = recent(seen(index as string, dir, names), await $.clock.now())
    return [week.length
      ? { status: 'WARN', name: 'defects', detail: `${week.length} in ${WINDOW_DAYS} days, newest ${week[0]!.title} (/base-defects lists them)` }
      : { status: 'PASS', name: 'defects', detail: `none in ${WINDOW_DAYS} days` }]
  } catch {
    return [{ status: 'SKIP', name: 'defects', detail: 'the reports did not answer' }]
  }
}

async function connect($: $, server: string): Promise<Row> {
  const name = `mcp:${server}`
  const timeout = $.clock.sleep(MCP_TIMEOUT_MS).then(() => null)
  let r
  try {
    r = await Promise.race([$.mcp.connect(server), timeout])
  } catch (err) {
    return { status: 'FAIL', name, detail: err instanceof Error ? err.message : String(err) }
  }
  if (r === null) return { status: 'FAIL', name, detail: `no answer in ${MCP_TIMEOUT_MS / 1000} s` }
  if (r.isConnected) return { status: 'PASS', name, detail: `connected as ${r.server}` }
  if (server === LOCAL_SERVER) {
    return { status: 'WARN', name, detail: `${r.message} — the Figma desktop app serves it (Dev Mode); base:figma-reader falls back to the REST API` }
  }
  if (r.reason === 'disabled') return { status: 'WARN', name, detail: `turned off: ${r.message}` }
  if (r.reason === 'auth') return { status: 'FAIL', name, detail: `needs sign-in — /mcp, then authenticate ${server}: ${r.message}` }
  return { status: 'FAIL', name, detail: `${r.reason}: ${r.message}` }
}

/** One row per server in base's own manifest, connected in parallel. */
async function mcpRows($: $): Promise<Row[]> {
  let servers: string[]
  try {
    const manifest = JSON.parse(await $.fs.read(`${$.plugin.root}/.claude-plugin/plugin.json`)) as { mcpServers?: unknown }
    servers = manifest.mcpServers && typeof manifest.mcpServers === 'object' ? Object.keys(manifest.mcpServers) : []
  } catch {
    return [{ status: 'FAIL', name: 'mcp', detail: "base's manifest is unreadable: no server to check" }]
  }
  if (!servers.length) return [{ status: 'SKIP', name: 'mcp', detail: 'no mcpServers in the manifest' }]
  return Promise.all(servers.map(s => connect($, s)))
}

/**
 * A static `slim` FAIL for a slim that is loaded anyway (a `--plugin-dir` load has no install record)
 * reads as a warning: the session has what base needs.
 */
export function reconcile(rows: Row[]): Row[] {
  const live = rows.find(r => r.name === 'slim-live')?.status === 'PASS'
  return rows.map(r =>
    live && r.name === 'slim' && r.status === 'FAIL' && r.detail.startsWith('not installed')
      ? { status: 'WARN', name: 'slim', detail: 'not in installed_plugins.json, yet loaded this session (a --plugin-dir load?)' }
      : r,
  )
}

export function age(ms: number): string {
  const s = Math.max(0, Math.round(ms / 1000))
  if (s < 60) return `${s}s`
  if (s < 3600) return `${Math.floor(s / 60)}m`
  if (s < 48 * 3600) return `${Math.floor(s / 3600)}h`
  return `${Math.floor(s / 86400)}d`
}

export function summary(rows: Row[]): string {
  const n = { PASS: 0, FAIL: 0, SKIP: 0, WARN: 0 }
  for (const r of rows) n[r.status]++
  return `${n.PASS} passed, ${n.FAIL} failed, ${n.SKIP} skipped${n.WARN ? `, ${n.WARN} warned` : ''}`
}

export function render(root: string, rows: Row[], tail: string[]): string {
  const width = rows.reduce((w, r) => Math.max(w, r.name.length), 0)
  return [
    `base doctor — plugin root: ${root}`,
    ...rows.map(r => `${r.status}  ${r.name.padEnd(width)}  ${r.detail}`),
    `doctor: ${summary(rows)}`,
    '',
    ...tail,
  ].join('\n')
}

async function eventTail($: $): Promise<string[]> {
  if ((await $.env.get('BASE_EVENT_LOG')) === '0') return ['base events: off (BASE_EVENT_LOG=0)']
  const list = await read($, events)
  if (!list.length) return ['base events: none yet']
  const now = await $.clock.now()
  const shown = list.slice(-TAIL)
  return [
    `base events (last ${shown.length} of ${list.length}, newest last):`,
    ...shown.map(ev => `  ${age(now - ev.atMs).padStart(4)}  ${ev.kind.padEnd(9)}  ${ev.text}`),
  ]
}

async function logDoctor($: $, text: string): Promise<void> {
  try {
    if ((await $.env.get('BASE_EVENT_LOG')) === '0') return
    const ev: BaseEvent = { atMs: await $.clock.now(), kind: 'doctor', text }
    await update($, events, l => pushEvent(l, ev))
    await logLine(diskOf($), ev)
  } catch {}
}

export function registerDoctor(on: On): void {
  // Matchers apart from base's other start hooks: one unmatched hook per event per plugin.
  on('session.start', { cwd: /$/ }, async ($, e, next) => {
    const r = await next(e)
    await arm($, true)
    return r
  })

  on('prompt.submit', { text: /$/ }, async ($, e, next) => {
    const r = await next(e)
    await arm($, false)
    return r
  })

  on('command.run', { command: COMMAND.name }, async $ => {
    const [fixed, live, defects, mcp] = await Promise.all([staticRows($), liveRows($), defectRows($), mcpRows($)])
    const rows = reconcile([...fixed, ...live, ...defects, ...mcp])
    const tail = await eventTail($)
    await logDoctor($, summary(rows))
    return { text: render($.plugin.root, rows, tail) }
  })
}

